commands.command:
mysql -uroot -p"$ROOT_PW" -e "
CREATE DATABASE IF NOT EXISTS appdb;
CREATE TABLE IF NOT EXISTS appdb.orders (
  id INT PRIMARY KEY AUTO_INCREMENT,
  customer VARCHAR(64),
  amount DECIMAL(10,2),
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
INSERT INTO appdb.orders (customer, amount) VALUES
 ('acme-corp', 120.50), ('globex', 75.00), ('initech', 300.25), ('umbrella', 42.10), ('soylent', 999.99);
SELECT COUNT(*), SUM(amount) FROM appdb.orders;
"
